return-response.set-body:
@{
                        var category = (context.Request.Url.Query.GetValueOrDefault("category", "outdoor") ?? "outdoor").ToLower();
                        var products = new JArray();
                        if (category == "outdoor") {
                            products.Add(new JObject(new JProperty("name", "Trail backpack 30L"), new JProperty("sku", "ZV-OUT-001"), new JProperty("priceEur", 89.90), new JProperty("inStock", true)));
                            products.Add(new JObject(new JProperty("name", "Ultralight tent"), new JProperty("sku", "ZV-OUT-002"), new JProperty("priceEur", 249.00), new JProperty("inStock", true)));
                            products.Add(new JObject(new JProperty("name", "Headlamp 400lm"), new JProperty("sku", "ZV-OUT-003"), new JProperty("priceEur", 34.50), new JProperty("inStock", true)));
                        } else if (category == "kitchen") {
                            products.Add(new JObject(new JProperty("name", "Cast iron skillet"), new JProperty("sku", "ZV-KIT-001"), new JProperty("priceEur", 45.00), new JProperty("inStock", true)));
                            products.Add(new JObject(new JProperty("name", "Chef knife 20cm"), new JProperty("sku", "ZV-KIT-002"), new JProperty("priceEur", 79.00), new JProperty("inStock", true)));
                            products.Add(new JObject(new JProperty("name", "Espresso grinder"), new JProperty("sku", "ZV-KIT-003"), new JProperty("priceEur", 129.00), new JProperty("inStock", true)));
                        } else if (category == "electronics") {
                            products.Add(new JObject(new JProperty("name", "Noise-cancelling headphones"), new JProperty("sku", "ZV-ELE-001"), new JProperty("priceEur", 199.00), new JProperty("inStock", true)));
                            products.Add(new JObject(new JProperty("name", "USB-C dock"), new JProperty("sku", "ZV-ELE-002"), new JProperty("priceEur", 149.00), new JProperty("inStock", true)));
                            products.Add(new JObject(new JProperty("name", "Smart speaker"), new JProperty("sku", "ZV-ELE-003"), new JProperty("priceEur", 99.00), new JProperty("inStock", true)));
                        }
                        return new JObject(new JProperty("category", category), new JProperty("products", products)).ToString();
                    }

@{
                        var orderId = context.Request.MatchedParameters.GetValueOrDefault("orderId", "unknown");
                        var statuses = new [] { "Out for delivery", "Shipped", "Processing", "Delivered" };
                        var status = statuses[orderId.Length % statuses.Length];
                        return new JObject(
                            new JProperty("orderId", orderId),
                            new JProperty("status", status),
                            new JProperty("carrier", "Zava Express"),
                            new JProperty("estimatedDelivery", DateTime.UtcNow.AddDays(2).ToString("yyyy-MM-dd"))).ToString();
                    }
